def _build_component_06():
    def solve(data):
        from itertools import product

        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        options = []
        for name in names:
            versions = sorted(row["version"] for row in packages[name]
                              if row["version"] not in blocked.get(name, []))
            if name in pins:
                versions = [v for v in versions if v == pins[name]]
            options.append([-1] + versions)

        best_vector = None
        best_result = None
        for vector in product(*options):
            selected = {name: version for name, version in zip(names, vector)
                        if version != -1}
            valid = True
            for name, (low, high) in roots.items():
                if name not in selected or not low <= selected[name] <= high:
                    valid = False
                    break
            if not valid:
                continue

            edges = {name: [] for name in selected}
            closure = set(roots)
            pending = list(roots)
            while pending and valid:
                name = pending.pop()
                if name not in selected:
                    valid = False
                    break
                row = next(row for row in packages[name]
                           if row["version"] == selected[name])
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    if other not in selected or not dep["min"] <= selected[other] <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(other)
                    if other not in closure:
                        closure.add(other)
                        pending.append(other)
            if not valid or set(selected) != closure:
                continue

            state = {}
            def visit(name):
                if state.get(name) == 1:
                    return False
                if state.get(name) == 2:
                    return True
                state[name] = 1
                if any(not visit(other) for other in edges[name]):
                    return False
                state[name] = 2
                return True
            if not all(visit(name) for name in selected):
                continue

            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_result = selected
        if best_result is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_result}
    return solve


def _build_component_07():
    def solve(data):
        from itertools import combinations

        jobs = data["jobs"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        k = data["k"]
        options = [job for job in jobs if job["id"] not in blocked]
        best_value = None
        best_ids = None

        for group in combinations(options, k):
            ids = {job["id"] for job in group}
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in group:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(name, 0) <= high
                   for name, (low, high) in quotas.items()):
                continue
            # Sweep interval endpoints; ends are processed before starts at the
            # same time because the intervals are half-open.
            points = []
            for job in group:
                points.append((job["start"], 1))
                points.append((job["end"], -1))
            active = maximum = 0
            for _, delta in sorted(points, key=lambda point: (point[0], point[1])):
                active += delta
                maximum = max(maximum, active)
            if maximum > 2:
                continue
            value = sum(job["value"] for job in group)
            sorted_ids = sorted(ids)
            if (best_value is None or value > best_value or
                    (value == best_value and sorted_ids < best_ids)):
                best_value, best_ids = value, sorted_ids

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _build_component_08():
    def solve(data):
        import heapq

        required = data.get("required", [])
        bit_for = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        source = data["source"]
        initial_mask = bit_for.get(source, 0)
        initial = (source, initial_mask, data["coupons"])
        distance = {initial: data["start"]}
        queue = [(data["start"], source, initial_mask, data["coupons"])]
        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distance.get(state) != time:
                continue
            if node == data["target"] and mask == full:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                choices = [(edge["duration"], remaining)]
                if remaining:
                    duration = max(2, edge["duration"] - edge.get("discount", 0))
                    choices.append((duration, remaining - 1))
                for duration, next_remaining in choices:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | bit_for.get(next_node, 0)
                    next_state = (next_node, next_mask, next_remaining)
                    if arrival < distance.get(next_state, float("inf")):
                        distance[next_state] = arrival
                        heapq.heappush(queue, (arrival, next_node, next_mask,
                                               next_remaining))
        return {"arrival": None}
    return solve


